/// Weakly Compressible SPH pressure computation via the Tait equation of state.
#[derive(Debug, Clone)]
pub struct WcSphPressure {
    /// Rest density (kg/m³).
    pub rho0: f64,
    /// Reference speed of sound (m/s).
    pub c0: f64,
    /// Tait exponent (typically 7 for water).
    pub gamma: f64,
}
impl WcSphPressure {
    /// Create a new `WcSphPressure` instance.
    pub fn new(rho0: f64, c0: f64, gamma: f64) -> Self {
        Self { rho0, c0, gamma }
    }
    /// Compute pressure from density using the Tait EOS.
    pub fn pressure(&self, rho: f64) -> f64 {
        tait_eos(rho, self.rho0, self.c0, self.gamma)
    }
    /// CFL-limited time step for sound-speed constraint.
    ///
    /// `dt = 0.4 * h / c0`
    pub fn cfl_dt(&self, h: f64) -> f64 {
        0.4 * h / self.c0
    }
    /// Alias for [`cfl_dt`](Self::cfl_dt).
    pub fn sound_speed_cfl_dt(&self, h: f64) -> f64 {
        self.cfl_dt(h)
    }
}
/// Incompressible SPH (ISPH) — projection-based pressure solver (simplified).
///
/// Solves a pressure Poisson equation (PPE) to enforce divergence-free velocity.
#[derive(Debug, Clone)]
pub struct IsphPressure {
    /// Rest density (kg/m³).
    pub rho0: f64,
}
impl IsphPressure {
    /// Create a new `IsphPressure` instance.
    pub fn new(rho0: f64) -> Self {
        Self { rho0 }
    }
    /// Compute the velocity divergence at particle `i` using SPH summation.
    ///
    /// `div(v)_i = Σ_j (m_j/rho_j) (v_j - v_i) · ∇W_ij`
    ///
    /// The kernel gradient `∇W_ij` for a cubic-spline-like kernel is
    /// approximated here as `-r_ij / (h * |r_ij|²)` with a compact-support
    /// cut-off at `|r_ij| > h` for simplicity.
    pub fn divergence_velocity(
        positions: &[[f64; 3]],
        velocities: &[[f64; 3]],
        masses: &[f64],
        densities: &[f64],
        h: f64,
        i: usize,
    ) -> f64 {
        let pi = positions[i];
        let vi = velocities[i];
        let mut div = 0.0_f64;
        for j in 0..positions.len() {
            if j == i {
                continue;
            }
            let r = [
                positions[j][0] - pi[0],
                positions[j][1] - pi[1],
                positions[j][2] - pi[2],
            ];
            let r_len2 = r[0] * r[0] + r[1] * r[1] + r[2] * r[2];
            let r_len = r_len2.sqrt();
            if r_len >= h || r_len < 1e-12 {
                continue;
            }
            let grad_w = [
                -r[0] / (h * r_len2),
                -r[1] / (h * r_len2),
                -r[2] / (h * r_len2),
            ];
            let dv = [
                velocities[j][0] - vi[0],
                velocities[j][1] - vi[1],
                velocities[j][2] - vi[2],
            ];
            let dot = dv[0] * grad_w[0] + dv[1] * grad_w[1] + dv[2] * grad_w[2];
            div += (masses[j] / densities[j]) * dot;
        }
        div
    }
    /// One Jacobi iteration for the pressure Poisson equation.
    ///
    /// Solves `A p = rhs` where `aij` encodes the off-diagonal coefficients
    /// and the diagonal is inferred as `- Σ_j a_ij` (standard Laplacian form).
    ///
    /// Returns the updated pressure vector.
    pub fn pressure_poisson_jacobi_step(
        pressures: &[f64],
        rhs: &[f64],
        aij: &[Vec<(usize, f64)>],
    ) -> Vec<f64> {
        let n = pressures.len();
        let mut p_new = vec![0.0_f64; n];
        for i in 0..n {
            let diag: f64 = -aij[i].iter().map(|&(_, a)| a).sum::<f64>();
            if diag.abs() < 1e-14 {
                p_new[i] = pressures[i];
                continue;
            }
            let off: f64 = aij[i].iter().map(|&(j, a)| a * pressures[j]).sum();
            p_new[i] = (rhs[i] - off) / diag;
        }
        p_new
    }
}
/// Predictive-Corrective Incompressible SPH (PCISPH) pressure solver.
///
/// Reference: Solenthaler & Pajarola 2009.
#[derive(Debug, Clone)]
pub struct PciSph {
    /// Rest density (kg/m³).
    pub rho0: f64,
    /// Pressure correction scaling factor δ.
    pub delta: f64,
}
impl PciSph {
    /// Build a `PciSph` instance.
    ///
    /// `delta` is computed from a simplified lattice-based estimate of the
    /// kernel gradient sum for `n_neighbors` uniformly-distributed neighbors
    /// within smoothing length `h`.
    pub fn new(rho0: f64, h: f64, n_neighbors: usize) -> Self {
        let delta = Self::compute_delta(h, n_neighbors);
        Self { rho0, delta }
    }
    /// Simplified δ formula: `1 / (2 * sum_kernel_sq / rho0²)` estimate.
    ///
    /// In practice the exact sum requires the actual kernel gradient norms,
    /// so here we approximate by assuming each neighbor contributes a
    /// characteristic gradient magnitude of `1/h² * (1/n_neighbors)`.
    pub fn compute_delta(h: f64, n_neighbors: usize) -> f64 {
        let n = n_neighbors.max(1) as f64;
        h * h * h * h / (2.0 * n)
    }
    /// Euler-forward density prediction: `rho_i + drho_dt * dt`.
    pub fn predict_density(&self, rho: f64, drho_dt: f64, dt: f64) -> f64 {
        rho + drho_dt * dt
    }
    /// Density error: `rho_pred - rho0`.
    pub fn density_error(&self, rho_pred: f64) -> f64 {
        rho_pred - self.rho0
    }
    /// Pressure correction step: `p += delta * rho_error`.
    pub fn pressure_update(&self, p: f64, rho_error: f64) -> f64 {
        p + self.delta * rho_error
    }
    /// Check convergence: `max |rho_error| < tol * rho0`.
    pub fn converged(&self, rho_errors: &[f64], tol: f64) -> bool {
        rho_errors.iter().map(|e| e.abs()).fold(0.0_f64, f64::max) < tol * self.rho0
    }
}
/// Tracks solver performance history and recommends the best solver.
pub struct ResidualBasedSelector {
    /// Performance history.
    pub history: Vec<SolverPerformanceEntry>,
    /// Maximum history size.
    pub max_history: usize,
}
impl ResidualBasedSelector {
    /// Create a new selector.
    pub fn new(max_history: usize) -> Self {
        Self {
            history: Vec::new(),
            max_history,
        }
    }
    /// Record a solver performance entry.
    pub fn record(&mut self, entry: SolverPerformanceEntry) {
        self.history.push(entry);
        if self.history.len() > self.max_history {
            self.history.remove(0);
        }
    }
    /// Recommend the solver with the lowest average residual.
    pub fn recommend(&self) -> SolverType {
        if self.history.is_empty() {
            return SolverType::Wcsph;
        }
        let mut wcsph_sum = 0.0_f64;
        let mut wcsph_count = 0_usize;
        let mut pcisph_sum = 0.0_f64;
        let mut pcisph_count = 0_usize;
        let mut iisph_sum = 0.0_f64;
        let mut iisph_count = 0_usize;
        for e in &self.history {
            match e.solver_type {
                SolverType::Wcsph => {
                    wcsph_sum += e.residual;
                    wcsph_count += 1;
                }
                SolverType::Pcisph => {
                    pcisph_sum += e.residual;
                    pcisph_count += 1;
                }
                SolverType::Iisph => {
                    iisph_sum += e.residual;
                    iisph_count += 1;
                }
            }
        }
        let avg = |sum: f64, count: usize| -> f64 {
            if count == 0 {
                f64::MAX
            } else {
                sum / count as f64
            }
        };
        let wcsph_avg = avg(wcsph_sum, wcsph_count);
        let pcisph_avg = avg(pcisph_sum, pcisph_count);
        let iisph_avg = avg(iisph_sum, iisph_count);
        if wcsph_avg <= pcisph_avg && wcsph_avg <= iisph_avg {
            SolverType::Wcsph
        } else if pcisph_avg <= iisph_avg {
            SolverType::Pcisph
        } else {
            SolverType::Iisph
        }
    }
    /// Number of entries recorded.
    pub fn history_len(&self) -> usize {
        self.history.len()
    }
}
/// Divergence-Free SPH (DFSPH) pressure solver.
///
/// Implements the two-pass scheme from Bender & Koschier (2015):
///   1. **Divergence-free solve** — enforces zero velocity divergence via an
///      iterative pressure correction to eliminate spurious compressibility.
///   2. **Density-invariant solve** — enforces constant density (i.e. `ρ = ρ₀`)
///      by correcting density errors from the previous time step.
///
/// Each pass uses a relaxed Jacobi iteration driven by a per-particle
/// "alpha" preconditioning coefficient.
#[derive(Debug, Clone)]
pub struct DfsphSolverSimple {
    /// Rest density ρ₀ \[kg/m³\].
    pub rest_density: f64,
    /// Relaxation factor ω ∈ (0, 2) for the Jacobi update.
    pub omega: f64,
    /// Maximum iterations for the divergence-free pass.
    pub max_iter_density: usize,
    /// Convergence tolerance for divergence (1/s).
    pub tol_divergence: f64,
    /// Convergence tolerance for density error (fraction of ρ₀).
    pub tol_density: f64,
}
impl DfsphSolverSimple {
    /// Create a new `DfsphSolverSimple`.
    pub fn new(
        rest_density: f64,
        omega: f64,
        max_iter_density: usize,
        tol_divergence: f64,
        tol_density: f64,
    ) -> Self {
        Self {
            rest_density,
            omega,
            max_iter_density,
            tol_divergence,
            tol_density,
        }
    }
    /// Pre-compute the per-particle DFSPH `alpha_i` coefficient.
    ///
    /// `alpha_i = rho_i / (sum_j m_j * |grad_W_ij|)^2`
    ///
    /// Neighbours are given as `(j, r_ij, grad_W_hat_ij)` where
    /// `grad_W_hat_ij` is the unit-normalised kernel gradient direction
    /// scaled by `|∇W_ij|`.
    ///
    /// # Arguments
    /// * `positions` – Particle positions.
    /// * `masses`    – Particle masses.
    /// * `neighbors` – For each particle i, list of `(j, r_ij, grad_w_ij)`.
    /// * `h`         – Smoothing length.
    pub fn compute_alpha(
        &self,
        positions: &[[f64; 3]],
        masses: &[f64],
        neighbors: &[Vec<(usize, f64, [f64; 3])>],
        h: f64,
    ) -> Vec<f64> {
        let n = positions.len();
        let mut alphas = vec![0.0_f64; n];
        for i in 0..n {
            let mut sum_grad2 = 0.0_f64;
            let mut sum_grad_vec = [0.0_f64; 3];
            for &(j, r_ij, grad_w) in &neighbors[i] {
                let mj = masses[j];
                let gw_mag2 = grad_w[0] * grad_w[0] + grad_w[1] * grad_w[1] + grad_w[2] * grad_w[2];
                sum_grad2 += mj * mj * gw_mag2;
                sum_grad_vec[0] += mj * grad_w[0];
                sum_grad_vec[1] += mj * grad_w[1];
                sum_grad_vec[2] += mj * grad_w[2];
                let _ = r_ij;
                let _ = h;
            }
            let sv_mag2 = sum_grad_vec[0] * sum_grad_vec[0]
                + sum_grad_vec[1] * sum_grad_vec[1]
                + sum_grad_vec[2] * sum_grad_vec[2];
            let denom = sum_grad2 + sv_mag2;
            if denom > 1e-20 {
                alphas[i] = 1.0 / denom;
            }
        }
        alphas
    }
    /// Compute the velocity divergence for particle `i`.
    ///
    /// `D_i = sum_j m_j * (v_i - v_j) · ∇W_ij`
    pub fn velocity_divergence(
        &self,
        i: usize,
        velocities: &[[f64; 3]],
        masses: &[f64],
        densities: &[f64],
        neighbors: &[Vec<(usize, f64, [f64; 3])>],
    ) -> f64 {
        let mut div = 0.0_f64;
        let rho_i = densities[i].max(1e-14);
        for &(j, _r_ij, grad_w) in &neighbors[i] {
            let mj = masses[j];
            let dv = [
                velocities[i][0] - velocities[j][0],
                velocities[i][1] - velocities[j][1],
                velocities[i][2] - velocities[j][2],
            ];
            let dot = dv[0] * grad_w[0] + dv[1] * grad_w[1] + dv[2] * grad_w[2];
            div += mj / rho_i * dot;
        }
        div
    }
    /// **Divergence-free pressure step** (pass 1 of DFSPH).
    ///
    /// Iterates a pressure correction to drive `∇·v → 0`.
    ///
    /// Returns `(pressures, iterations_used)`.
    ///
    /// # Arguments
    /// * `positions`  – Current positions.
    /// * `velocities` – Current velocities (will not be mutated).
    /// * `masses`     – Particle masses.
    /// * `densities`  – Current densities.
    /// * `neighbors`  – Sparse neighbour list `(j, r_ij, grad_W_ij)`.
    /// * `h`          – Smoothing length.
    /// * `dt`         – Time step.
    pub fn divergence_free_step(
        &self,
        positions: &[[f64; 3]],
        velocities: &[[f64; 3]],
        masses: &[f64],
        densities: &[f64],
        neighbors: &[Vec<(usize, f64, [f64; 3])>],
        h: f64,
        dt: f64,
    ) -> (Vec<f64>, usize) {
        let n = positions.len();
        let alphas = self.compute_alpha(positions, masses, neighbors, h);
        let mut pressures = vec![0.0_f64; n];
        for iter in 0..self.max_iter_density {
            let divergences: Vec<f64> = (0..n)
                .map(|i| self.velocity_divergence(i, velocities, masses, densities, neighbors))
                .collect();
            let max_div = divergences.iter().map(|d| d.abs()).fold(0.0_f64, f64::max);
            if max_div < self.tol_divergence {
                return (pressures, iter + 1);
            }
            for i in 0..n {
                let rho_i = densities[i].max(1e-14);
                let dp = self.omega * rho_i * alphas[i] * divergences[i] / dt.max(1e-30);
                pressures[i] = (pressures[i] + dp).max(0.0);
            }
        }
        (pressures, self.max_iter_density)
    }
    /// **Density-invariant pressure step** (pass 2 of DFSPH).
    ///
    /// Iterates a pressure correction to drive `ρ → ρ₀`.
    ///
    /// Returns `(pressures, iterations_used)`.
    pub fn density_invariant_step(
        &self,
        positions: &[[f64; 3]],
        _velocities: &[[f64; 3]],
        masses: &[f64],
        densities: &[f64],
        neighbors: &[Vec<(usize, f64, [f64; 3])>],
        h: f64,
        dt: f64,
    ) -> (Vec<f64>, usize) {
        let n = positions.len();
        let alphas = self.compute_alpha(positions, masses, neighbors, h);
        let mut pressures = vec![0.0_f64; n];
        for iter in 0..self.max_iter_density {
            let errors: Vec<f64> = (0..n)
                .map(|i| (densities[i] - self.rest_density) / self.rest_density)
                .collect();
            let max_err = errors.iter().map(|e| e.abs()).fold(0.0_f64, f64::max);
            if max_err < self.tol_density {
                return (pressures, iter + 1);
            }
            let dt2 = (dt * dt).max(1e-30);
            for i in 0..n {
                let rho_i = densities[i].max(1e-14);
                let dp = self.omega * rho_i * alphas[i] * errors[i] / dt2;
                pressures[i] = (pressures[i] + dp).max(0.0);
            }
        }
        (pressures, self.max_iter_density)
    }
}
impl DfsphSolverSimple {
    /// Compute the density source term for particle `i` (DFSPH, Bender et al. 2015).
    ///
    /// The source term is the Lagrangian time derivative of density:
    ///   `s_i = Dρ_i/Dt = sum_j m_j (v_i - v_j) · ∇W_ij`
    ///
    /// A positive value means the local density is increasing (compression).
    ///
    /// # Arguments
    /// * `i`          – Particle index.
    /// * `velocities` – Velocity array.
    /// * `masses`     – Mass array.
    /// * `neighbors`  – For each particle i, list of `(j, r_ij, grad_W_ij)`.
    pub fn compute_source_term(
        &self,
        i: usize,
        velocities: &[[f64; 3]],
        masses: &[f64],
        neighbors: &[Vec<(usize, f64, [f64; 3])>],
    ) -> f64 {
        let mut source = 0.0_f64;
        for &(j, _r_ij, grad_w) in &neighbors[i] {
            let mj = masses[j];
            let dv = [
                velocities[i][0] - velocities[j][0],
                velocities[i][1] - velocities[j][1],
                velocities[i][2] - velocities[j][2],
            ];
            source += mj * (dv[0] * grad_w[0] + dv[1] * grad_w[1] + dv[2] * grad_w[2]);
        }
        source
    }
    /// Compute the source terms for all particles.
    ///
    /// Convenience wrapper that calls [`compute_source_term`](Self::compute_source_term)
    /// for every particle index.
    pub fn compute_all_source_terms(
        &self,
        velocities: &[[f64; 3]],
        masses: &[f64],
        neighbors: &[Vec<(usize, f64, [f64; 3])>],
    ) -> Vec<f64> {
        (0..velocities.len())
            .map(|i| self.compute_source_term(i, velocities, masses, neighbors))
            .collect()
    }
}
/// Framework for comparing pressure solver performance.
pub struct SolverComparison {
    /// Rest density.
    pub rho0: f64,
    /// Speed of sound (for WCSPH).
    pub c0: f64,
    /// Tait exponent.
    pub gamma: f64,
    /// PCISPH delta.
    pub pcisph_delta: f64,
    /// IISPH relaxation.
    pub iisph_omega: f64,
    /// Maximum iterations for iterative solvers.
    pub max_iter: usize,
    /// Convergence tolerance.
    pub tolerance: f64,
}
impl SolverComparison {
    /// Create a comparison framework with default parameters.
    pub fn new(rho0: f64, c0: f64) -> Self {
        Self {
            rho0,
            c0,
            gamma: 7.0,
            pcisph_delta: 0.5,
            iisph_omega: 0.5,
            max_iter: 100,
            tolerance: 0.001,
        }
    }
    /// Run WCSPH solver on the given densities.
    pub fn run_wcsph(&self, densities: &[f64]) -> SolverBenchmarkResult {
        let solver = WcSphSolver::new(self.rho0, self.c0, self.gamma);
        let mut pressures = vec![0.0; densities.len()];
        solver.compute_all_pressures(densities, &mut pressures);
        let max_err = densities
            .iter()
            .map(|&rho| (rho - self.rho0).abs())
            .fold(0.0_f64, f64::max);
        let avg_err = if densities.is_empty() {
            0.0
        } else {
            densities
                .iter()
                .map(|&rho| (rho - self.rho0).abs())
                .sum::<f64>()
                / densities.len() as f64
        };
        SolverBenchmarkResult {
            solver_type: SolverType::Wcsph,
            iterations: 0,
            max_density_error: max_err,
            avg_density_error: avg_err,
            pressures,
        }
    }
    /// Run PCISPH solver on predicted densities.
    pub fn run_pcisph(&self, predicted_densities: &[f64]) -> SolverBenchmarkResult {
        let solver = PcisphSolverSimple {
            rho0: self.rho0,
            delta: self.pcisph_delta,
            max_iter: self.max_iter,
            tolerance: self.tolerance,
        };
        let (pressures, iters) = solver.solve(predicted_densities);
        let max_err = predicted_densities
            .iter()
            .map(|&rho| (rho - self.rho0).abs())
            .fold(0.0_f64, f64::max);
        let avg_err = if predicted_densities.is_empty() {
            0.0
        } else {
            predicted_densities
                .iter()
                .map(|&rho| (rho - self.rho0).abs())
                .sum::<f64>()
                / predicted_densities.len() as f64
        };
        SolverBenchmarkResult {
            solver_type: SolverType::Pcisph,
            iterations: iters,
            max_density_error: max_err,
            avg_density_error: avg_err,
            pressures,
        }
    }
    /// Run IISPH solver on a pre-assembled PPE system.
    pub fn run_iisph(&self, rhs: &[f64], aij: &[Vec<(usize, f64)>]) -> SolverBenchmarkResult {
        let solver = IisphSolverSimple {
            rho0: self.rho0,
            omega: self.iisph_omega,
            max_iter: self.max_iter,
            tolerance: self.tolerance,
        };
        let (pressures, iters, residual) = solver.solve_pressure_poisson(rhs, aij);
        SolverBenchmarkResult {
            solver_type: SolverType::Iisph,
            iterations: iters,
            max_density_error: residual,
            avg_density_error: residual,
            pressures,
        }
    }
}
