/// Full PCISPH solver (Solenthaler & Pajarola 2009) operating on plain arrays.
///
/// Unlike [`PcisphSolverSimple`], this struct maintains a [`PcisphState`] and
/// exposes separate prediction, error-computation, and correction methods so
/// that callers can interleave SPH density summation with the iterative loop.
#[derive(Debug, Clone)]
pub struct PcisphSolver {
    /// Rest density ρ₀ \[kg/m³\].
    pub rest_density: f64,
    /// Pre-computed stiffness (δ) parameter.
    pub delta: f64,
    /// Maximum number of correction iterations.
    pub max_iter: usize,
    /// Density error threshold η (fraction of ρ₀).
    pub eta: f64,
}
impl PcisphSolver {
    /// Construct a `PcisphSolver`.
    ///
    /// `delta` is estimated from the smoothing length `h` using the lattice-
    /// based approximation from §4 of the PCISPH paper.
    pub fn new(rest_density: f64, h: f64, max_iter: usize, eta: f64) -> Self {
        let delta = h * h * h * h / (2.0 * 32.0);
        Self {
            rest_density,
            delta,
            max_iter,
            eta,
        }
    }
    /// Predict velocities and positions for all particles given current forces.
    ///
    /// `predicted_v = v + (F/m) * dt`
    /// `predicted_x = x + predicted_v * dt`
    pub fn predict_velocities_positions(
        &self,
        positions: &[[f64; 3]],
        velocities: &[[f64; 3]],
        forces: &[[f64; 3]],
        masses: &[f64],
        dt: f64,
        state: &mut PcisphState,
    ) {
        let n = positions.len();
        for i in 0..n {
            let inv_m = 1.0 / masses[i].max(1e-30);
            let mut pv = [0.0_f64; 3];
            for k in 0..3 {
                pv[k] = velocities[i][k] + forces[i][k] * inv_m * dt;
                state.predicted_velocities[i][k] = pv[k];
                state.predicted_positions[i][k] = positions[i][k] + pv[k] * dt;
            }
        }
    }
    /// Compute density errors: `ρ_pred - ρ₀` for each particle.
    pub fn compute_density_error(&self, state: &PcisphState) -> Vec<f64> {
        state
            .predicted_densities
            .iter()
            .map(|&rho| rho - self.rest_density)
            .collect()
    }
    /// Compute per-particle pressure corrections: `δP_i = delta * (ρ_pred - ρ₀)`.
    ///
    /// Corrections are stored in `state.pressure_corrections`.
    pub fn compute_pressure_correction(&self, state: &mut PcisphState) {
        for i in 0..state.len() {
            let err = state.predicted_densities[i] - self.rest_density;
            state.pressure_corrections[i] = self.delta * err;
        }
    }
    /// Check convergence: `max |ρ_err| / ρ₀ < eta`.
    pub fn converged(&self, errors: &[f64]) -> bool {
        errors.iter().map(|e| e.abs()).fold(0.0_f64, f64::max) < self.eta * self.rest_density
    }
    /// Full PCISPH prediction-correction loop (Solenthaler & Pajarola 2009).
    ///
    /// Runs up to `max_iter` iterations of:
    ///   1. Predict positions/velocities from current forces.
    ///   2. Estimate predicted densities via kernel summation.
    ///   3. Compute pressure correction from density error.
    ///   4. Check convergence.
    ///
    /// Returns the final pressure array and the number of iterations used.
    ///
    /// # Arguments
    /// * `positions`   – Current particle positions.
    /// * `velocities`  – Current particle velocities.
    /// * `masses`      – Particle masses.
    /// * `non_pressure_forces` – Forces excluding pressure (gravity, viscosity, etc.).
    /// * `neighbors`   – For each particle `i`, list of `(j, r_ij, w_ij)` tuples.
    /// * `h`           – Smoothing length.
    /// * `dt`          – Time step.
    pub fn predict_correct_step(
        &self,
        positions: &[[f64; 3]],
        velocities: &[[f64; 3]],
        masses: &[f64],
        non_pressure_forces: &[[f64; 3]],
        neighbors: &[Vec<(usize, f64, f64)>],
        h: f64,
        dt: f64,
    ) -> (Vec<f64>, usize) {
        let n = positions.len();
        let mut state = PcisphState::new(n);
        let mut pressures = vec![0.0_f64; n];
        for iter in 0..self.max_iter {
            for i in 0..n {
                let inv_m = 1.0 / masses[i].max(1e-30);
                for k in 0..3 {
                    let a_k = non_pressure_forces[i][k] * inv_m;
                    state.predicted_velocities[i][k] = velocities[i][k] + a_k * dt;
                    state.predicted_positions[i][k] =
                        positions[i][k] + state.predicted_velocities[i][k] * dt;
                }
            }
            for i in 0..n {
                let mut rho_pred = 0.0_f64;
                for &(j, _r_ij, w_ij) in &neighbors[i] {
                    rho_pred += masses[j] * w_ij;
                }
                let w_self = Self::cubic_w_3d(0.0, h);
                rho_pred += masses[i] * w_self;
                state.predicted_densities[i] = rho_pred;
            }
            self.compute_pressure_correction(&mut state);
            for (i, pr) in pressures.iter_mut().enumerate().take(n) {
                *pr = (*pr + state.pressure_corrections[i]).max(0.0);
            }
            let errors = self.compute_density_error(&state);
            if self.converged(&errors) {
                return (pressures, iter + 1);
            }
        }
        (pressures, self.max_iter)
    }
    /// 3-D cubic spline kernel value at `r/h`.
    fn cubic_w_3d(r: f64, h: f64) -> f64 {
        let q = r / h;
        if q > 2.0 {
            return 0.0;
        }
        let sigma = 1.0 / (std::f64::consts::PI * h * h * h);
        if q <= 1.0 {
            sigma * (1.0 - 1.5 * q * q + 0.75 * q * q * q)
        } else {
            sigma * 0.25 * (2.0 - q).powi(3)
        }
    }
}
impl PcisphSolver {
    /// Compute a corrected velocity for particle `i` from its pressure correction.
    ///
    /// In PCISPH, once the pressure correction ΔP_i is known, the corrected
    /// acceleration on particle `i` is:
    ///   `a_corr_i = -sum_j m_j * (ΔP_i/ρ_i² + ΔP_j/ρ_j²) * ∇W_ij`
    ///
    /// For a simplified single-particle update with a scalar pressure gradient
    /// (suitable for testing/educational use):
    ///   `v_corr_i = v_pred_i + dt * (-ΔP_i / (rho_i * h)) * n_hat`
    ///
    /// where `n_hat` is the pressure gradient direction (normalized).
    ///
    /// # Arguments
    /// * `v_predicted`        – Predicted velocity of particle i \[m/s\].
    /// * `pressure_correction` – Scalar pressure correction ΔP_i \[Pa\].
    /// * `rho_i`              – Predicted density of particle i \[kg/m³\].
    /// * `h`                  – Smoothing length \[m\].
    /// * `dt`                 – Time step \[s\].
    /// * `gradient_dir`       – Unit direction of the local pressure gradient.
    pub fn compute_predicted_velocity_correction(
        &self,
        v_predicted: [f64; 3],
        pressure_correction: f64,
        rho_i: f64,
        h: f64,
        dt: f64,
        gradient_dir: [f64; 3],
    ) -> [f64; 3] {
        let rho = rho_i.max(1e-14);
        let h = h.max(1e-30);
        let scale = -pressure_correction * dt / (rho * h);
        [
            v_predicted[0] + scale * gradient_dir[0],
            v_predicted[1] + scale * gradient_dir[1],
            v_predicted[2] + scale * gradient_dir[2],
        ]
    }
}
/// Diagonal (Jacobi) preconditioner for the IISPH pressure Poisson system.
///
/// Stores the precomputed diagonal coefficients `a_ii` and provides a
/// preconditioned Jacobi step that is more stable than raw Jacobi at high
/// relaxation factors.
#[derive(Debug, Clone)]
pub struct IisphDiagonalPreconditioner {
    /// Precomputed diagonal coefficients (a_ii for each particle).
    pub diag: Vec<f64>,
    /// Relaxation factor ω.
    pub omega: f64,
    /// Rest density ρ₀ for convergence checking.
    pub rho0: f64,
}
impl IisphDiagonalPreconditioner {
    /// Build the preconditioner from the off-diagonal system.
    pub fn build(aij: &[Vec<(usize, f64)>], omega: f64, rho0: f64) -> Self {
        let diag: Vec<f64> = aij
            .iter()
            .map(|row| -row.iter().map(|&(_, a)| a).sum::<f64>())
            .collect();
        Self { diag, omega, rho0 }
    }
    /// One preconditioned Jacobi step.
    ///
    /// Returns `(p_new, max_residual)`.
    pub fn step(&self, p: &[f64], rhs: &[f64], aij: &[Vec<(usize, f64)>]) -> (Vec<f64>, f64) {
        let n = p.len();
        let mut p_new = vec![0.0_f64; n];
        let mut max_res = 0.0_f64;
        for i in 0..n {
            let aii = self.diag[i];
            if aii.abs() < 1e-20 {
                p_new[i] = p[i];
                continue;
            }
            let off: f64 = aij[i].iter().map(|&(j, a)| a * p[j]).sum();
            let target = (rhs[i] - off) / aii;
            p_new[i] = ((1.0 - self.omega) * p[i] + self.omega * target).max(0.0);
            let res = (aii * p_new[i] + off - rhs[i]).abs();
            if res > max_res {
                max_res = res;
            }
        }
        (p_new, max_res)
    }
    /// Run until convergence or `max_iter` steps.
    pub fn solve(
        &self,
        rhs: &[f64],
        aij: &[Vec<(usize, f64)>],
        max_iter: usize,
        tol: f64,
    ) -> (Vec<f64>, usize, f64) {
        let n = rhs.len();
        let mut p = vec![0.0_f64; n];
        let mut residual = f64::MAX;
        for iter in 0..max_iter {
            let (p_new, res) = self.step(&p, rhs, aij);
            p = p_new;
            residual = res;
            if residual < tol * self.rho0 {
                return (p, iter + 1, residual);
            }
        }
        (p, max_iter, residual)
    }
}
/// A family of Tait equation of state variants parameterized by rest density,
/// sound speed, and exponent.
#[derive(Debug, Clone)]
pub struct TaitEosFamily {
    /// Rest density ρ₀ \[kg/m³\].
    pub rho0: f64,
    /// Speed of sound c₀ \[m/s\].
    pub c0: f64,
    /// Exponent γ (7 for water, 1.4 for ideal gas).
    pub gamma: f64,
    /// Bulk modulus B = ρ₀ c₀² / γ.
    pub big_b: f64,
}
impl TaitEosFamily {
    /// Create a new EOS family.
    pub fn new(rho0: f64, c0: f64, gamma: f64) -> Self {
        let big_b = rho0 * c0 * c0 / gamma;
        Self {
            rho0,
            c0,
            gamma,
            big_b,
        }
    }
    /// Standard water EOS (ρ₀=1000, c₀=100, γ=7).
    pub fn water() -> Self {
        Self::new(1000.0, 100.0, 7.0)
    }
    /// Ideal gas EOS (ρ₀=1.2, c₀=343, γ=1.4).
    pub fn air() -> Self {
        Self::new(1.2, 343.0, 1.4)
    }
    /// Pressure from density.
    pub fn pressure(&self, rho: f64) -> f64 {
        self.big_b * ((rho / self.rho0).powf(self.gamma) - 1.0)
    }
    /// Density from pressure (inverse Tait).
    pub fn density_from_pressure(&self, p: f64) -> f64 {
        self.rho0 * (p / self.big_b + 1.0).powf(1.0 / self.gamma)
    }
    /// Local speed of sound at density `rho`: c = c₀ (ρ/ρ₀)^((γ-1)/2).
    pub fn sound_speed(&self, rho: f64) -> f64 {
        self.c0 * (rho / self.rho0).powf((self.gamma - 1.0) / 2.0)
    }
    /// CFL timestep: `dt_cfl = 0.4 h / c(ρ)`.
    pub fn cfl_dt(&self, h: f64, rho: f64) -> f64 {
        0.4 * h / self.sound_speed(rho).max(1e-20)
    }
    /// Pressure for all particles in-place.
    pub fn compute_all(&self, densities: &[f64], pressures: &mut [f64]) {
        for (p_out, &rho) in pressures.iter_mut().zip(densities.iter()) {
            *p_out = self.pressure(rho);
        }
    }
    /// Maximum safe time step across all densities.
    pub fn min_cfl_dt(&self, h: f64, densities: &[f64]) -> f64 {
        densities
            .iter()
            .map(|&rho| self.cfl_dt(h, rho))
            .fold(f64::INFINITY, f64::min)
    }
}
